        title: 'The Adventures of Sherlock Holmes',
        get coverImg() { return getCoverImagePath('mystery', 'The Adventures of Sherlock Holmes') || getPlaceholderCover('mystery', 'The Adventures of Sherlock Holmes', 'Arthur Conan Doyle') },
