        get coverImg() { return getCoverImagePath('mystery', 'The Hound of the Baskervilles') || getPlaceholderCover('mystery', 'The Hound of the Baskervilles', 'Arthur Conan Doyle') },
        author: 'Arthur Conan Doyle',
