        title: 'Jujitsuffragettes',
        get coverImg() { return getCoverImagePath('non_fiction', 'Jujitsuffragettes') || getPlaceholderCover('non_fiction', 'Jujitsuffragettes', 'Various Authors') },
        author: 'Various Authors',
